=<!DOCTYPE html>
<html lang="en" xmlns="http://www.w3.org/1999/xhtml" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office">
<head>
<meta charset="utf-8"> 
<meta name="viewport" content="width=device-width"> 
<meta http-equiv="X-UA-Compatible" content="IE=edge"> 
<meta name="x-apple-disable-message-reformatting"> 
<!-- FORCE DARK MODE: This tells iOS/Gmail we support dark mode natively -->
<meta name="color-scheme" content="dark">
<meta name="supported-color-schemes" content="dark">

<title>Incoming Transmission</title>

<style>
  @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&display=swap');

  /* CLIENT-SPECIFIC RESETS */
  body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }
  table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
  img { -ms-interpolation-mode: bicubic; }

  /* FORCE DARK BACKGROUND ON iOS */
  :root {
    color-scheme: dark;
    supported-color-schemes: dark;
  }

  body {
    background-color: #0f172a !important; /* Force Slate 900 */
    font-family: 'JetBrains Mono', 'Courier New', monospace;
    color: #e2e8f0 !important;
    margin: 0;
    padding: 0;
    width: 100% !important;
    height: 100% !important;
  }

  /* CONTAINER STYLES */
  .wrapper {
    width: 100%;
    table-layout: fixed;
    background-color: #0f172a;
    padding-bottom: 40px;
  }

  .main-box {
    max-width: 600px;
    margin: 0 auto;
    background-color: #1e293b; /* Slate 800 */
    border: 1px solid #334155;
    border-radius: 8px;
    overflow: hidden;
    /* Neon Glow effect */
    box-shadow: 0 0 15px rgba(14, 165, 233, 0.15); 
  }

  /* HUD HEADER */
  .header {
    background-color: #0f172a;
    border-bottom: 2px solid #0ea5e9;
    padding: 20px;
    text-align: left;
  }

  .header h1 {
    color: #0ea5e9;
    font-size: 16px;
    margin: 0;
    letter-spacing: 2px;
    text-transform: uppercase;
    display: inline-block;
  }

  /* BLINKING CURSOR ANIMATION */
  .cursor {
    display: inline-block;
    width: 10px;
    height: 16px;
    background-color: #0ea5e9;
    animation: blink 1s step-end infinite;
    vertical-align: middle;
    margin-left: 5px;
  }
  @keyframes blink { 50% { opacity: 0; } }

  /* TECH DATA GRID */
  .meta-grid {
    display: table;
    width: 100%;
    background-color: #162032;
    border-bottom: 1px solid #334155;
    font-size: 10px;
    color: #64748b;
  }
  .meta-cell {
    display: table-cell;
    padding: 10px 20px;
    border-right: 1px solid #334155;
    width: 33%;
  }
  .meta-label { text-transform: uppercase; display: block; margin-bottom: 2px; color: #475569; }
  .meta-value { color: #94a3b8; font-weight: bold; }

  /* CONTENT BODY */
  .content {
    padding: 30px;
    color: #f1f5f9;
    font-size: 15px;
    line-height: 1.6;
    white-space: pre-line; /* Respects LLM paragraphs */
  }

  /* FOOTER */
  .footer {
    background-color: #0f172a;
    padding: 15px 30px;
    border-top: 1px solid #334155;
    font-size: 10px;
    color: #475569;
    display: flex;
    justify-content: space-between;
  }

  .secure-badge {
    color: #10b981; /* Green */
    border: 1px solid #10b981;
    padding: 2px 6px;
    border-radius: 4px;
    text-transform: uppercase;
    font-size: 9px;
  }

</style>
</head>
<body>
  <div class="wrapper">
    <br>
    <div class="main-box">

      <!-- HEADER -->
      <div class="header">
        <h1>// Jarvis_Link_Established<span class="cursor"></span></h1>
      </div>

      <!-- TECH SPECS GRID (The "Techie" Tricks) -->
      <div class="meta-grid">
        <div class="meta-cell">
          <span class="meta-label">Protocol</span>
          <span class="meta-value">SMTP_SECURE</span>
        </div>
        <div class="meta-cell">
          <span class="meta-label">Timestamp</span>
          <!-- n8n Timestamp Trick -->
          <span class="meta-value">{{ $now.toUTC().toFormat("HH:mm:ss") }} UTC</span>
        </div>
        <div class="meta-cell" style="border-right: none;">
          <span class="meta-label">Ref ID</span>
          <!-- n8n Execution ID Trick -->
          <span class="meta-value">{{ $execution.id }}</span>
        </div>
      </div>

      <!-- MAIN CONTENT -->
      <div class="content">
        {{ $json.body.body }}
      </div>

      <!-- FOOTER -->
      <div class="footer">
        <table width="100%">
          <tr>
            <td align="left">SYSTEM: ONLINE</td>
            <td align="right"><span class="secure-badge">Encrypted: AES-256</span></td>
          </tr>
        </table>
      </div>

    </div>
  </div>
</body>
</html>
